"use strict";
// utest.cmd.civet

import {LOG, DBG, ERR} from 'logger'
import {
	undef, defined, notdefined, assert,
	colorize, decolorize, write, writeln, clearScreen,
	} from 'base'
import {isString} from 'datatypes'
import {cmdTitle, f, dashes, EXEC} from 'llutils'
import {
	isFile, rmDir, withExt, findFile, allFilesMatching,
	parsePath, toRelPath,
	} from 'fsys'
import {execCmd, TExecResult} from 'exec'
import {doCompileCivet} from 'civet'
import {
	TProcSpec, procFiles, procOneFile, compileAllLibs, compileAllUnitTests,
	} from 'proc-files'
import {DUMP, OL} from 'nice'
import {CTimer} from 'timer'
import {getCmdArgs, inspect} from 'cmd-args'
import {doUnitTest} from 'compile'

const [
	lStubs,
	{force, serial, line: lineNum}
	] = getCmdArgs('utest', {
		_:       {range: [1,99], desc: "stubs to test or 'all'"},
		force:   {flag: 'f', desc: 'force recompile of libs and tests'},
		serial:  {flag: 's', desc: 'run serially'},
		line:    {valType: 'integer', desc: 'line number to test'}
		})

// ---------------------------------------------------------------------------

await EXEC(async () => {
	debugger
	const [compileOK, lCompileResults] = await compileAllLibs({force})
	if (!compileOK) {
		ERR("Some libs failed compile")
		console.log(lCompileResults)
		Deno.exit(-1)
	}

	if (lStubs[0] === 'all') {

		const [compileUTOK, lCompileUTResults] = await compileAllUnitTests({force})
		if (!compileUTOK) {
			ERR("Some unit tests failed compile")
			console.log(lCompileUTResults)
			Deno.exit(-1)
		}

		// --- At this point, all libs and unit tests have been compiled

		assert(notdefined(lineNum), "Can't use -line with 'all'")
		assert(!inspect, "Can't use -I with 'all'")
		if (!inspect) {
			rmDir('./coverage', {clear: true})
		}

		LOG(cmdTitle("UNIT TEST ALL"))
		const timer = new CTimer()

		// --- Print the header
		LOG(f`${'Lib'}:-14 ${'OK'}:4 ${'Fail'}:4 ${'Time'}:8`)
		LOG([dashes(14), dashes(4), dashes(4), dashes(8)].join(' '))

		if (serial) {
			for (const path of allFilesMatching('**/*.{lib,cmd,parse}.ts')) {
				const hResult = await procOneFile(path, doUnitTest, {
					capture: true,
					quiet: true
					})
				showResult(path, hResult)
			}
		}
		else {
			await procFiles([doUnitTest, ['**/*.test.ts']], {
				callback: showResult,
				quiet: true
				})
		}

		console.log(`TIME TAKEN: ${timer.timeTakenStr()}`)
		if (!inspect) {
			// --- Create HTML coverage file
			write("Building coverage report...")
			const hResult = await execCmd('deno', ['coverage', '--html'])
			writeln("Done")
		}
	}
	else {
		for (const stub of lStubs) {
			LOG(cmdTitle(`RUN UNIT TEST ${stub}`))

			const fileName = (
				  stub.includes('.')
				? `${stub}.test.civet`
				: `${stub}.lib.test.civet`   // --- default is a 'lib' unit test
				)
			const path = findFile(fileName)
			if (notdefined(path)) {
				ERR(`No such file: ${fileName}`)
				continue
			}

			// --- compile the test file
			await procOneFile(path, doCompileCivet, {force, quiet: true})

			const tsPath = withExt(path, '.ts')
			const hResult = await procOneFile(tsPath, doUnitTest, {
				lineNum,
				inspect
				})
		}
	}
})

// ---------------------------------------------------------------------------

const showResult = (
		path: string,
		hResult: TExecResult
		): void => {

	if (!hResult.success) {
		ERR(`Unit Test of ${path} failed`)
		DUMP(hResult.stderr, 'STDERR')
	}

	const h = parsePath(path)
	const stub = h.stub.endsWith('.lib') ? h.stub.replace('.lib', '') : h.stub

	const stdout = hResult.stdout || 'BAD'
	const lMatches = decolorize(stdout).match(/ok\s*\|\s*(\d+)\s*passed\s*\|\s*(\d+)\s*failed\s*\((\d+)(s|ms)\)/)
	if (defined(lMatches)) {
		const [_, nOk, nBad, tm, units] = lMatches
		const nOkStr  = (
			  (nOk === '0')
			? colorize(nOk, 'red')
			: colorize(nOk, 'green')
			)
		const nBadStr = (
			  (nBad === '0')
			? colorize(nBad, 'green')
			: colorize(nBad, 'red')
			)
		const timeStr = (
			  (units === 's')
			? `${tm}  s`
			: `${tm} ${units}`
			)
		LOG(f`${stub}:-14 ${nOkStr}:4 ${nBadStr}:4 ${timeStr}:8`)
	}
	else {
		LOG(hResult.stdout)
	}
}


